const require_defaults = require("../utils/defaults.js");
const require_index = require("../useResizeObserver/index.js");
let react = require("react");
//#region src/useMeasure/index.ts
const defaultState = {
	x: 0,
	y: 0,
	width: 0,
	height: 0,
	top: 0,
	left: 0,
	bottom: 0,
	right: 0
};
const useMeasure = (target, options = require_defaults.defaultOptions) => {
	const [rect, setRect] = (0, react.useState)(defaultState);
	return [rect, require_index.useResizeObserver(target, (entries) => {
		if (entries[0]) {
			const { x, y, width, height, top, left, bottom, right } = entries[0].contentRect;
			setRect({
				x,
				y,
				width,
				height,
				top,
				left,
				bottom,
				right
			});
		}
	}, options)];
};
//#endregion
exports.useMeasure = useMeasure;
